import fs from 'node:fs';
import crypto from 'node:crypto';
import { buildRequestedQualitativeSlotContract } from './lib/chat/retrievalContextAssembler.js';
import { validateExactFactAnswer } from './lib/chat/factContract.js';
const data=JSON.parse(fs.readFileSync('docs/audits/evidence/rag-retest-2026-08-31-95104077/qualitative-replay.json','utf8'));
const original=JSON.parse(fs.readFileSync(data.canonical_slots_file,'utf8')).trace.query_plan.semantic_turn_contract.requested_facts;
const identity={required:true,matched:true,confidence:'high',selectedDocumentId:'d'};
const results=data.cases.map(test=>{
 const fixture=data.evidence.find(row=>row.slot===test.slot);
 const evidence=test.use_correct_slot4_evidence?data.correct_slot4_source.text:fixture.text;
 const slot=original.find(row=>row.index===test.slot);
 const questionPlan={mode:'specific_research_fact',semantic_candidates:{requested_fact_slots:{complete:true,slots:[slot]}}};
 const contract=buildRequestedQualitativeSlotContract({questionPlan,renderedGroups:[{sourceId:'d',docId:'d',bodies:[evidence]}],specificResearchFactQuestion:true,documentIdentityEvidence:identity}).trace;
 if(test.counterfactual_remove_provide)contract.slots[0].action_object_bindings=contract.slots[0].action_object_bindings.filter(binding=>binding.action_family!=='provide');
 const result=validateExactFactAnswer({reply:test.reply_from_evidence?evidence:test.reply,sources:[{source_id:'d',document_id:'d',evidenceText:'Teenuste uuring\n'+evidence}],retrievalMeta:{documentIdentityEvidence:identity,queryPlan:{mode:'specific_research_fact',semantic_turn_contract:{requested_facts:[slot],requested_fact_contract:{complete:true}}},requestedQualitativeSlotContract:contract}});
 const hash=crypto.createHash('sha256').update(evidence).digest('hex');
 return {id:test.id,expected:test.expected,actual:result.passed?'PASS':'FAIL',reason:result.trace.reason,qualitative_checked:result.trace.requested_qualitative_contract_checked,evidence_hash:hash,fixture_hash_matches:hash===(test.use_correct_slot4_evidence?data.correct_slot4_source.fragment_hash:fixture.fragment_hash),recorded_result_matches:(result.passed?'PASS':'FAIL')===test.actual};
});
console.log(JSON.stringify({runtime_code_release:data.runtime_code_release,scope:data.scope,results},null,2));
